style.css:
@-moz-document regexp("https:\/\/voice\.google\.com\/u\/[0-9]+\/messages.*") {
gv-batch-thread-selection-header,
gv-batch-thread-select-header {
    position: absolute;
    top: 0;
  	width: 100%;
    background: #ffffff;
    display: block;
    box-sizing: border-box;
    z-index: 10;
}

gv-batch-thread-selection-header div,
gv-batch-thread-select-header div {
    animation: slide-down 0.4s ease;
}

@keyframes slide-down {
    0% {
        opacity: 0;
        transform: translateY(-5px);
    }
    100% {
        opacity: 1;
        transform: translateY(0);
    }
}
}
